<?php
namespace App\Services;use App\Models\{Employee,AttendanceRecord,AdvancePayment,ExtraDuty,Payslip};use Illuminate\Support\Facades\DB;
class PayslipService{public function generate(Employee $e,?int $pid,int $m,int $y,?int $uid=null):Payslip{return DB::transaction(function()use($e,$pid,$m,$y,$uid){$q=AttendanceRecord::where('employee_id',$e->id)->when($pid,fn($x)=>$x->where('project_id',$pid))->where('month',$m)->where('year',$y);$nh=(clone $q)->where('status','present')->where('is_extra_duty',false)->sum('hours');$dw=(clone $q)->where('status','present')->count();$ad=(clone $q)->where('status','absent')->count();$eh=ExtraDuty::where('employee_id',$e->id)->when($pid,fn($x)=>$x->where('project_id',$pid))->whereMonth('duty_date',$m)->whereYear('duty_date',$y)->where('approval_status','approved')->sum('hours_worked');$ea=ExtraDuty::where('employee_id',$e->id)->when($pid,fn($x)=>$x->where('project_id',$pid))->whereMonth('duty_date',$m)->whereYear('duty_date',$y)->where('approval_status','approved')->sum('amount');$adv=AdvancePayment::where('employee_id',$e->id)->when($pid,fn($x)=>$x->where('project_id',$pid))->whereMonth('payment_date',$m)->whereYear('payment_date',$y)->sum('amount');$normal=$e->monthly_salary?:$nh*($e->hourly_rate?:0);$gross=$normal+$ea;return Payslip::updateOrCreate(['employee_id'=>$e->id,'project_id'=>$pid,'month'=>$m,'year'=>$y,'status'=>'draft'],['total_hours'=>$nh+$eh,'normal_hours'=>$nh,'extra_duty_hours'=>$eh,'days_worked'=>$dw,'absent_days'=>$ad,'hourly_rate'=>$e->hourly_rate,'monthly_salary'=>$e->monthly_salary,'normal_salary'=>$normal,'extra_duty_amount'=>$ea,'gross_salary'=>$gross,'advance_deduction'=>$adv,'net_salary'=>$gross-$adv,'generated_by'=>$uid,'generated_at'=>now()]);});}public function finalize(Payslip $p):Payslip{$p->update(['status'=>'final']);return $p;}}
